import{_ as i,o as t,c as u,a2 as n}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Jedwali la Muhtasari wa Historia","description":"","frontmatter":{},"headers":[],"relativePath":"sw/93-编年史简表.md","filePath":"sw/93-编年史简表.md","lastUpdated":1789183869000}'),k={name:"sw/93-编年史简表.md"};function d(w,a,m,e,o,h){return t(),u("div",null,[...a[0]||(a[0]=[n('<h1 id="jedwali-la-muhtasari-wa-historia" tabindex="-1">Jedwali la Muhtasari wa Historia <a class="header-anchor" href="#jedwali-la-muhtasari-wa-historia" aria-label="Permalink to &quot;Jedwali la Muhtasari wa Historia&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya hati</td><td>93</td></tr><tr><td>Moduli</td><td>Viambatanisho na Vifaa vya Rujia</td></tr><tr><td>Maneno muhimu</td><td>historia, mgawanyo wa enzi, matukio muhimu, nodi za kihistoria, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-maelezo-ya-historia" tabindex="-1">1. Maelezo ya Historia <a class="header-anchor" href="#_1-maelezo-ya-historia" aria-label="Permalink to &quot;1. Maelezo ya Historia&quot;">​</a></h2><p>Jedwali hili la muhtasari linategemea wakati wa kawaida wa Hengyuanzhou, na linarekodi kwa mpangilio wa enzi matukio muhimu ya kihistoria na nodi za msingi katika safari ya maendeleo ya Ustaarabu wa Usawa wa Nanga. Muda unafikia kutoka katika enzi la zamani la enzi la kabla ya nanga hadi matarajio ya baadaye ya enzi la usawa wa kati ya nyota. Kila enzi linaorodhesha muda wa kuanza na kumalizika, tabia za enzi, na matukio muhimu. Jedwali hili la muhtasari ni fahirisi ya kihistoria iliyojengwa kwa ukubwa mkubwa; kwa historia ya kina ya kila enzi, tafadhali rejelea maandishi maalum ya hati 70-79.</p><h2 id="_2-muhtasari-wa-mgawanyo-wa-enzi" tabindex="-1">2. Muhtasari wa Mgawanyo wa Enzi <a class="header-anchor" href="#_2-muhtasari-wa-mgawanyo-wa-enzi" aria-label="Permalink to &quot;2. Muhtasari wa Mgawanyo wa Enzi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nambari ya enzi</th><th>Jina la enzi</th><th>Muda wa kuanza na kumalizika (mwaka wa kawaida wa Hengyuanzhou)</th><th>Muda</th><th>Tabia ya msingi</th></tr></thead><tbody><tr><td>Enzi ya kwanza</td><td>Enzi ya kabla ya nanga</td><td>Takriban -10 bilioni hadi -10,000 miaka</td><td>Takriban 10 bilioni miaka</td><td>Mfumo wa u cultivating wa kuitoaji unaongoza, mzunguko wa kuinuliwa na kuanguka kwa utamaduni</td></tr><tr><td>Enzi ya pili</td><td>Enzi ya uamsho wa nanga</td><td>-10,000 hadi -1,000 miaka</td><td>Takriban 9,000 miaka</td><td>Mchakato wa nanga umegunduliwa na kutumika kwa awali</td></tr><tr><td>Enzi ya tatu</td><td>Kipindi cha usanifu wa mfumo wa usawa</td><td>-1,000 hadi -100 miaka</td><td>Takriban 900 miaka</td><td>Mfumo wa taasisi wa Ustaarabu wa Usawa wa Nanga unajengwa polepole</td></tr><tr><td>Enzi ya nne</td><td>Kipindi cha kufunguliwa kwa mfumo wa mia tatu</td><td>-100 hadi -50 miaka</td><td>Takriban 50 miaka</td><td>Mfumo wa u cultivating wa asili wa mia tatu umefunguliwa kabisa</td></tr><tr><td>Enzi ya tano</td><td>Kipindi cha mkakati wa uanzishaji wa 20%</td><td>-50 miaka hadi mwaka wa asili</td><td>Takriban 50 miaka</td><td>20% ya viumbe vyenye fahamu zinaanzishwa kuwa watu wenye nguvu za juu za usawa</td></tr><tr><td>Enzi ya sita</td><td>Enzi ya kuinua kiwango cha kwanza</td><td>Mwaka wa asili hadi 100 miaka</td><td>100 miaka</td><td>Ustaarabu wa usawa unafikia kwa mara ya kwanza kuinua kiwango cha hatua</td></tr><tr><td>Enzi ya saba</td><td>Enzi ya jamhuri ya kabila zote</td><td>100 hadi 500 miaka</td><td>400 miaka</td><td>Jamhuri ya kabila zote imeanzishwa rasmi, muunganisho wa kabila zinazozungumzana umeongezeka</td></tr><tr><td>Enzi ya nane</td><td>Enzi ya uchunguzi wa kati ya usawa</td><td>500 hadi 2,000 miaka</td><td>1,500 miaka</td><td>Uchunguzi wa kikubwa wa kati ya usawa na shughuli za kale zinaanza</td></tr><tr><td>Enzi ya tisa</td><td>Enzi ya usawa wa kati ya nyota</td><td>2,000 miaka hadi baadaye</td><td>Inaendelea</td><td>Mtandao wa usawa wa kiulimwengu umejengwa, kuinua kiwango cha jumla kinakuendelea</td></tr></tbody></table><p>Kumbukumbu: &quot;Mwaka wa asili&quot; unarejelea mwaka ambao Ustaarabu wa Usawa wa Nanga ulitangaza rasmi uanzishwaji wake, na hutumika kama hatua ya mgawanyo ya tarehe za kihistoria.</p><h2 id="_3-enzi-ya-kabla-ya-nanga-takriban-10-bilioni-hadi-10-000-miaka" tabindex="-1">3. Enzi ya kabla ya nanga (Takriban -10 bilioni hadi -10,000 miaka) <a class="header-anchor" href="#_3-enzi-ya-kabla-ya-nanga-takriban-10-bilioni-hadi-10-000-miaka" aria-label="Permalink to &quot;3. Enzi ya kabla ya nanga (Takriban -10 bilioni hadi -10,000 miaka)&quot;">​</a></h2><p>Enzi ya kabla ya nanga ni enzi ya muda mrefu zaidi katika historia ya Hengyuanzhou, iliyodumu takriban bilioni kumi miaka. Tabia ya msingi ya enzi hii ni kwamba mfumo wa u cultivating wa kuitoaji uliongoza ulimwengu, na utamaduni ulizunguka mara kwa mara katika mzunguko wa &quot;kuinuliwa—kilele cha juu—kuitoaji—kuanguka&quot;.</p><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>Takriban -10 bilioni miaka</td><td>Mtandao wa sheria za Hengyuanzhou ulidumu, usawa wa kwanza wa vifaa ulijengwa, ulimwengu ulingia katika hali inayoweza kuishi</td></tr><tr><td>Takriban -8 bilioni miaka</td><td>Viumbe vya kwanza vya akili vimezaliwa katika usawa mbalimbali wa vifaa, mfumo wa u cultivating wa asili unaanza kuchipua</td></tr><tr><td>Takriban -5 bilioni miaka</td><td>Mfumo wa u cultivating wa kuitoaji unakuwa hatua zaidi, wenye nguvu wanabebiwa kwa kumeza wenye nguvu wa chini</td></tr><tr><td>Takriban -3 bilioni miaka</td><td>Vita vya kwanza vya kuitoaji vya kiulimwengu vilivunjika, utamaduni wa mikoa mbalimbali ya nyota ulipata mapigo ya uharibifu</td></tr><tr><td>Takriban -1 bilioni miaka</td><td>Uadhaifu wa mfumo wa kuitoaji unaanza kuonekana, entropy ya jumla ya ulimwengu inakua kwa kasi, rasilimali za u cultivating zinakwisha zaidi</td></tr><tr><td>Takriban -500 milioni miaka</td><td>Wafikiria wa kwanza wanaotafakari juu ya mfumo wa kuitoaji wanaonekana, mchanga wa mawazo ya usawa unaanza kuzalishwa</td></tr><tr><td>Takriban -100 milioni miaka</td><td>Utamaduni wa majaribio ya usawa wa ukubwa mdogo unaonekana katika mikoa mbalimbali ya nyota, lakini yote yameharibiwa na utamaduni wa kuitoaji</td></tr><tr><td>Takriban -1 milioni miaka</td><td>Ulimwengu kwa jumla ulingia katika &quot;kipindi cha kushuka kwa kuzingatia&quot;, idadi ya utamaduni na kiwango cha u cultivating zimepungua hadi kiwango cha chini cha kihistoria</td></tr><tr><td>Takriban -10,000 miaka</td><td>Mtu anayefanya u cultivating kutoka usawa wa kwanza kwa bahati anahisi nodi za kudumu katika mtandao wa sherea wakati wa u cultivating wa muda mrefu, mchakato wa nanga umegunduliwa kwa mara ya kwanza</td></tr></tbody></table><h2 id="_4-enzi-ya-uamsho-wa-nanga-10-000-hadi-1-000-miaka" tabindex="-1">4. Enzi ya uamsho wa nanga (-10,000 hadi -1,000 miaka) <a class="header-anchor" href="#_4-enzi-ya-uamsho-wa-nanga-10-000-hadi-1-000-miaka" aria-label="Permalink to &quot;4. Enzi ya uamsho wa nanga (-10,000 hadi -1,000 miaka)&quot;">​</a></h2><p>Enzi ya uamsho wa nanga ni kipindi cha mpito kutoka ugundujaji hadi matumizi ya awali ya mchakato wa nanga. Tabia ya msingi ya enzi hii ni ukomavu wa polepole wa teknolojia ya nanga na uenezi wa mawazo ya usawa.</p><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>-10,000 miaka</td><td>Mchakato wa nanga umegunduliwa kwa mara ya kwanza, mgunduja anaitaja &quot;nanga&quot;, na ananza utafiti wa mifumo</td></tr><tr><td>-9,000 miaka</td><td>Nanga ya kwanza ya bandia imejengwa kwa mafanikio, inaonyesha kuwa nanga inaweza kujengwa na kudumishwa kwa njia ya binadamu</td></tr><tr><td>-8,000 miaka</td><td>Teknolojia ya nanga inaanza kuenea katika eneo dogo, watu wa kwanza wa u cultivating wa nanga wanaonekana</td></tr><tr><td>-7,000 miaka</td><td>Imegunduliwa kuwa nanga inaweza kutumika kama msingi wa muunganisho wa kati ya usawa, safari ya kwanza ya kati ya usawa inayosaidiwa na nanga imerekodiwa kwa mafanikio</td></tr><tr><td>-6,000 miaka</td><td>Mawazo ya usawa na teknolojia ya nanga yanaanza kuunganishwa, hati za kwanza za kibunifu za &quot;usawa wa nanga&quot; zinachapishwa</td></tr><tr><td>-5,000 miaka</td><td>Mji-wa-taifa wa kwanza wa aina ya usawa uliojengwa kwa msingi wa nanga umeanzishwa, inaonyesha uwezekano wa mfumo wa usawa</td></tr><tr><td>-4,000 miaka</td><td>Utamaduni wa kuitoaji unashambulia mji-wa-taifa wa aina ya usawa, mji-wa-taifa wa usawa unalinda kwa mafanikio kupitia teknolojia ya nanga</td></tr><tr><td>-3,000 miaka</td><td>Mawazo ya usawa yanaenea katika mikoa mbalimbali ya nyota, utamaduni zaidi zaidi zinaanza kujaribu mabadiliko ya usawa</td></tr><tr><td>-2,000 miaka</td><td>&quot;Mkutano wa Usawa wa Kabila Zote&quot; wa kwanza umefanyika, wawakilishi wa makabila kadhaa wanajadili pamoja mustakabali wa utamaduni wa usawa</td></tr><tr><td>-1,000 miaka</td><td>Teknolojia ya nanga na mawazo ya usawa tayari yametimiza masharti ya kuanzisha utamaduni wa umoja, kipindi cha usanifu wa mfumo wa usawa kinaanza</td></tr></tbody></table><h2 id="_5-kipindi-cha-usanifu-wa-mfumo-wa-usawa-1-000-hadi-100-miaka" tabindex="-1">5. Kipindi cha usanifu wa mfumo wa usawa (-1,000 hadi -100 miaka) <a class="header-anchor" href="#_5-kipindi-cha-usanifu-wa-mfumo-wa-usawa-1-000-hadi-100-miaka" aria-label="Permalink to &quot;5. Kipindi cha usanifu wa mfumo wa usawa (-1,000 hadi -100 miaka)&quot;">​</a></h2><p>Kipindi cha usanifu wa mfumo wa usawa ni kipindi muhimu ambacho mfumo wa taasisi wa Ustaarabu wa Usawa wa Nanga unajengwa kutoka kwa kutokuwa hadi kuwepo.</p><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>-1,000 miaka</td><td>Kamati ya kuandaa Katiba ya Usawa imeanzishwa, inaanza kuandaa sheria ya msingi</td></tr><tr><td>-950 miaka</td><td>Rasimu ya &quot;Katiba ya Usawa&quot; imekamilika, inaanza kuomba maoni kwa upana kutoka kwa kabila zote</td></tr><tr><td>-900 miaka</td><td>&quot;Katiba ya Usawa&quot; imepitishwa kupitia kura ya taifa, inatekelezwa rasmi, Ustaarabu wa Usawa wa Nanga umetangazwa kuanzishwa</td></tr><tr><td>-850 miaka</td><td>Baraza la Nanga, Kamati ya Utendaji wa Usawa, Mahakama ya Usawa taasisi tatu kuu zimeanzishwa na kutekeleza</td></tr><tr><td>-800 miaka</td><td>Mchakato wa mkataba wa uzalishaji pamoja unaanza kutekelezwa katika nchi nzima</td></tr><tr><td>-700 miaka</td><td>&quot;Sheria ya Kazi ya Usawa&quot;, &quot;Sheria ya Ulinzi wa Watumiaji&quot; na sheria zingine za msingi zimetangazwa mfululizo</td></tr><tr><td>-600 miaka</td><td>Sheria tano za msaada za elimu, afya, makazi, mazingira, na kuzuia utawala wa soko zote zimetangazwa na kutekelezwa</td></tr><tr><td>-500 miaka</td><td>Kazi ya kuchimba na kupanga mfumo wa u cultivating wa asili wa mia tatu imeanzishwa rasmi</td></tr><tr><td>-400 miaka</td><td>Mia hamsini ya kwanza ya mifumo ya u cultivating wa asili imekamilika katika kupanga na kuthibitisha</td></tr><tr><td>-300 miaka</td><td>Matumizi ya teknolojia ya tunda la mara mbili yamepata maendeleo, teknolojia ya kuongeza makosa ya mara mia moja imekomaa</td></tr><tr><td>-200 miaka</td><td>Mia tatu kamili ya mifumo imekamilika katika kupanga, inaingia katika hatua ya mwisho ya kuthibitisha usalama</td></tr><tr><td>-100 miaka</td><td>Masharti ya kufunguliwa kamili ya mfumo wa u cultivating wa asili wa mia tatu yamekomaa, inaingia katika kipindi cha kufunguliwa</td></tr></tbody></table><h2 id="_6-kipindi-cha-kufunguliwa-kwa-mfumo-wa-mia-tatu-100-hadi-50-miaka" tabindex="-1">6. Kipindi cha kufunguliwa kwa mfumo wa mia tatu (-100 hadi -50 miaka) <a class="header-anchor" href="#_6-kipindi-cha-kufunguliwa-kwa-mfumo-wa-mia-tatu-100-hadi-50-miaka" aria-label="Permalink to &quot;6. Kipindi cha kufunguliwa kwa mfumo wa mia tatu (-100 hadi -50 miaka)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>-100 miaka</td><td>Mfumo wa u cultivating wa asili wa mia tatu umefunguliwa rasmi kwa bure kwa viumbe vyote vyenye fahamu katika ulimwengu</td></tr><tr><td>-90 miaka</td><td>Idadi ya watu wanaofanya u cultivating imeongezeka mara mia moja katika miaka kumi, &quot;kila mtu ana njia&quot; imetekelezwa kwa awali</td></tr><tr><td>-80 miaka</td><td>Misingi mitatu ya asili (kurudia makosa, mzunguko wa maisha, kupanga sheria za nafasi) inakuwa mifumo maarufu zaidi</td></tr><tr><td>-70 miaka</td><td>Watu wa kwanza wa u cultivating waliokufikia kiwango cha juu kupitia mfumo mpya wanaonekana, inaonyesha ufanisi wa mfumo</td></tr><tr><td>-60 miaka</td><td>Mtandao wa walimu umejengwa kabisa, watu wa u cultivating wa kiwango cha juu wanaanza kutimiza wajibu wa kisheria wa kuongoza watu wa u cultivating wa chini</td></tr><tr><td>-50 miaka</td><td>Kiwango cha u cultivating cha watu wote kimeongezeka kwa kiwango kikubwa, masharti ya mkakati wa uanzishaji wa 20% yamekomaa</td></tr></tbody></table><h2 id="_7-kipindi-cha-mkakati-wa-uanzishaji-wa-20-50-miaka-hadi-mwaka-wa-asili" tabindex="-1">7. Kipindi cha mkakati wa uanzishaji wa 20% (-50 miaka hadi mwaka wa asili) <a class="header-anchor" href="#_7-kipindi-cha-mkakati-wa-uanzishaji-wa-20-50-miaka-hadi-mwaka-wa-asili" aria-label="Permalink to &quot;7. Kipindi cha mkakati wa uanzishaji wa 20% (-50 miaka hadi mwaka wa asili)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>-50 miaka</td><td>Mkakati wa uanzishaji wa 20% umeanzishwa rasmi, lengo ni kuamsha 20% ya viumbe vyenye fahamu kuwa watu wenye nguvu za juu za usawa ndani ya miaka 50</td></tr><tr><td>-40 miaka</td><td>Watu wa kwanza wenye nguvu za juu za usawa wamezaliwa, kiwango cha uanzishaji kimefikia 5%</td></tr><tr><td>-30 miaka</td><td>Kiwango cha uanzishaji kimefikia 10%, watu wenye nguvu za juu za usawa wanaanza kuchukua jukumu la msingi katika kudumisha nanga</td></tr><tr><td>-20 miaka</td><td>Kiwango cha uanzishaji kimefikia 15%, kiwango cha u cultivating cha jumla cha ulimwengu kimefikia kuruka kwa ubora</td></tr><tr><td>-10 miaka</td><td>Kiwango cha uanzishaji kimefikia 18%, karibu na lengo la mkakati</td></tr><tr><td>Mwaka wa asili</td><td>Kiwango cha uanzishaji kimefikia 20.3%, mkakati wa uanzishaji wa 20% umekamilika kwa mafanikio, Ustaarabu wa Usawa wa Nanga unaingia katika enzi mpya</td></tr></tbody></table><h2 id="_8-enzi-ya-kuinua-kiwango-cha-kwanza-mwaka-wa-asili-hadi-100-miaka" tabindex="-1">8. Enzi ya kuinua kiwango cha kwanza (Mwaka wa asili hadi 100 miaka) <a class="header-anchor" href="#_8-enzi-ya-kuinua-kiwango-cha-kwanza-mwaka-wa-asili-hadi-100-miaka" aria-label="Permalink to &quot;8. Enzi ya kuinua kiwango cha kwanza (Mwaka wa asili hadi 100 miaka)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>Mwaka wa asili</td><td>Ustaarabu wa usawa umetangaza rasmi kuingia katika enzi ya kuinua kiwango, hatua ya kwanza ya njia ya kuinua kiwango cha hatua nne (msingi wa ukweli) imekamilika</td></tr><tr><td>20 miaka</td><td>Hatua ya pili (kuwezesha teknolojia) inaendelea kabisa, sheria za u cultivating na uhandisi wa teknolojia zimeunganishwa kwa kina</td></tr><tr><td>40 miaka</td><td>Teknolojia ya kioo cha nakala, teknolojia ya nafasi iliyotengwa zimefikia uzalishaji wa wingi wa uhandisi, kale za kati ya usawa zinaingia katika enzi ya kiwango</td></tr><tr><td>60 miaka</td><td>Watu wa kwanza wa darasa la kuinua kiwango cha ufahamu wamefikia kiwango cha juu, hatua ya tatu (mageuzi ya ufahamu) yanaanza</td></tr><tr><td>80 miaka</td><td>Ujenzi wa miundombinu ya eneo la ufahamu umekamilika, teknolojia ya kuhamisha ufahamu imekomaa kwa awali</td></tr><tr><td>100 miaka</td><td>Kuinua kiwango cha hatua ya kwanza kwa mafanikio, utamaduni wa usawa kwa jumla kuinua kiwango cha nusu cha mwelekeo</td></tr></tbody></table><h2 id="_9-enzi-ya-jamhuri-ya-kabila-zote-100-hadi-500-miaka" tabindex="-1">9. Enzi ya jamhuri ya kabila zote (100 hadi 500 miaka) <a class="header-anchor" href="#_9-enzi-ya-jamhuri-ya-kabila-zote-100-hadi-500-miaka" aria-label="Permalink to &quot;9. Enzi ya jamhuri ya kabila zote (100 hadi 500 miaka)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>100 miaka</td><td>Jamhuri ya kabila zote imetangazwa rasmi kuanzishwa, kabila zote za akili zimefikia muungano wa usawa ndani ya mfumo wa utamaduni wa usawa</td></tr><tr><td>150 miaka</td><td>Mkusanyiko wa orodha ya kabila zote umekamilika, inajumuisha kabila zote za akuli zinazojulikana</td></tr><tr><td>200 miaka</td><td>Ndoa za kati ya kabila na muunganisho wa kitamaduni yanakuwa kawaida, kabila mpya za mchanganyiko zinaanza kuonekana</td></tr><tr><td>300 miaka</td><td>Uenezi wa lugha ya kawaida ya kabila zote umekamilika, vikwazo vya mawasiliano ya kati ya kabila vimeondolewa kimsingi</td></tr><tr><td>400 miaka</td><td>Utamaduni wa kabila zote unaendelea kwa kasi kubwa, utamaduni wa jadi wa kila kabila umelindwa na kukuza ndani ya mfumo wa usawa</td></tr><tr><td>500 miaka</td><td>Jamhuri ya kabila zote inaingia katika kipindi cha ukomavu, masharti ya uchunguzi wa kati ya usawa yamekomaa kabisa</td></tr></tbody></table><h2 id="_10-enzi-ya-uchunguzi-wa-kati-ya-usawa-500-hadi-2-000-miaka" tabindex="-1">10. Enzi ya uchunguzi wa kati ya usawa (500 hadi 2.000 miaka) <a class="header-anchor" href="#_10-enzi-ya-uchunguzi-wa-kati-ya-usawa-500-hadi-2-000-miaka" aria-label="Permalink to &quot;10. Enzi ya uchunguzi wa kati ya usawa (500 hadi 2.000 miaka)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>500 miaka</td><td>Mpango wa uchunguzi wa kikubwa wa kati ya usawa umeanzishwa rasmi, ofisi ya usimamizi wa usawa imeanzishwa</td></tr><tr><td>600 miaka</td><td>Usawa uliochunguzwa umeongezeka zaidi ya elfu, hazina ya jumla ya mawasiliano ya usawa imejengwa kwa awali</td></tr><tr><td>800 miaka</td><td>Mpango wa kale wa mbali wa kioo cha nakala umekomaa kabisa, kale za kati ya usawa zinaingia katika enzi ya dhahabu</td></tr><tr><td>1.000 miaka</td><td>Teknolojia ya kurudia nyuma kwa muda imepata maendeleo, kanuni ya kuzingatia kwanza, kisha kuingilia kwa kikomo imeanzishwa rasmi</td></tr><tr><td>1.200 miaka</td><td>Usawa uliochunguzwa umeongezeka zaidi ya elfu kumi, uhusiano wa kidiplomasia umeanzishwa na kabila kadhaa za utamaduni wa usawa</td></tr><tr><td>1.500 miaka</td><td>Kanuni za maadili za kati ya usawa zinatekelezwa kabisa, mwingiliano kati ya utamaduni unaingia katika enzi ya viwango</td></tr><tr><td>1.800 miaka</td><td>Mchakato wa kuzuia utata wa muda umekomaa kabisa, kale za kurudia nyuma kwa muda zimefikia kiwango</td></tr><tr><td>2.000 miaka</td><td>Uchunguzi wa kati ya usawa umepata matokeo ya kupendeza, masharti ya enzi ya usawa wa kati ya nyota yamekomaa kabisa</td></tr></tbody></table><h2 id="_11-enzi-ya-usawa-wa-kati-ya-nyota-2-000-miaka-hadi-baadaye" tabindex="-1">11. Enzi ya usawa wa kati ya nyota (2.000 miaka hadi baadaye) <a class="header-anchor" href="#_11-enzi-ya-usawa-wa-kati-ya-nyota-2-000-miaka-hadi-baadaye" aria-label="Permalink to &quot;11. Enzi ya usawa wa kati ya nyota (2.000 miaka hadi baadaye)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nodi ya wakati</th><th>Matukio muhimu</th></tr></thead><tbody><tr><td>2.000 miaka</td><td>Enzi ya usawa wa kati ya nyota imefunguliwa rasmi, hatua ya nne (usawa wa kati ya nyota) inaendelea kabisa</td></tr><tr><td>2.500 miaka (matarajio)</td><td>Mtandao wa nanga wa kiulimwengu umejengwa kwa awali, unafunika usawa wote uliochunguzwa</td></tr><tr><td>3.000 miaka (matarajio)</td><td>Mfumo wa usawa wa kati ya usawa umekomaa, kabila zote zimefikia usawa wa kweli katika kiwango cha ulimwengu</td></tr><tr><td>5.000 miaka (matarajio)</td><td>Kuinua kiwango cha jumla cha ulimwengu kumekamilika, Hengyuanzhou inaingia katika hali ya kuwepo ya mwelekeo wa juu zaidi</td></tr><tr><td>Baadaye (matarajio)</td><td>Ustaarabu wa Usawa wa Nanga unaendelea kuchunguza nje ya ulimwengu, aneneza wazo la usawa hadi kuwepo kwa upana zaidi</td></tr></tbody></table><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Jedwali la muhtasari la historia ni epik ya kupambana ya Ustaarabu wa Usawa wa Nanga, kutoka ujinga hadi uamsho, kutoka udhaifu hadi nguvu, kutoka usawa wa mwenyewe hadi ulimwengu wote. Kila uingizwaji wa enzi ni ushahidi wa ushindi wa wazo la usawa dhidi ya wazo la kuitoaji, maendeleo ya utamaduni dhidi ya kushuka kwa ushenzi. Historia siyo vumbi la zamani, bali ni mbegu ya baadaye—kuelewa historia hii ni kuelewa utamaduni wa usawa unatoka wapi na unaenda wapi.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>70-Jedwali la Jumla la Mgawanyo wa Enzi</li><li>72-Enzi ya uamsho wa nanga</li><li>79-Matarajio ya Enzi ya usawa wa kati ya nyota</li></ul>',32)])])}const s=i(k,[["render",d]]);export{l as __pageData,s as default};
